PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "contractors" ("id" integer primary key autoincrement not null, "name" varchar not null, "bidang" varchar not null, "kualifikasi" varchar not null, "nib" varchar not null, "pj" varchar not null, "alamat" varchar not null, "email" varchar, "telepon" varchar, "rating" numeric not null default '5', "created_at" datetime, "updated_at" datetime, "status" varchar not null default 'approved');
CREATE TABLE IF NOT EXISTS "trainings" ("id" integer primary key autoincrement not null, "nama_pelatihan" varchar not null, "tanggal" date not null, "kuota" integer not null, "pendaftar_count" integer not null default '0', "status" varchar not null, "detail" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "regulations" ("id" integer primary key autoincrement not null, "judul" varchar not null, "nomor" varchar not null, "tahun" integer not null, "kategori" varchar not null, "deskripsi" text, "created_at" datetime, "updated_at" datetime, "file" varchar);
CREATE TABLE IF NOT EXISTS "news_items" ("id" integer primary key autoincrement not null, "judul" varchar not null, "konten" text not null, "tanggal" date not null, "kategori" varchar not null default 'Umum', "created_at" datetime, "updated_at" datetime, "cover_image" varchar, "status" varchar not null default 'publish');
CREATE TABLE IF NOT EXISTS "contractor_training" ("id" integer primary key autoincrement not null, "contractor_id" integer not null, "training_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("contractor_id") references "contractors"("id") on delete cascade, foreign key("training_id") references "trainings"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "role" varchar not null default 'admin_pupr', "contractor_id" integer, "nip" varchar, "bidang" varchar, foreign key("contractor_id") references "contractors"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "project_logs" ("id" integer primary key autoincrement not null, "project_id" integer not null, "user_id" integer, "action" varchar not null, "progress" numeric not null, "photo" varchar, "note" text, "created_at" datetime, "updated_at" datetime, foreign key("project_id") references "projects"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "activity_logs" ("id" integer primary key autoincrement not null, "user_id" integer, "email" varchar, "role" varchar, "action" varchar not null, "description" text, "ip_address" varchar, "user_agent" text, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "training_participants" ("id" integer primary key autoincrement not null, "training_id" integer not null, "nama_peserta" varchar not null, "nik" varchar not null, "instansi" varchar not null, "kontak" varchar not null, "created_at" datetime, "updated_at" datetime, foreign key("training_id") references "trainings"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "project_photos" ("id" integer primary key autoincrement not null, "project_id" integer not null, "project_log_id" integer, "path" varchar not null, "caption" varchar, "created_at" datetime, "updated_at" datetime, "type" varchar not null default 'progress', foreign key("project_id") references "projects"("id") on delete cascade, foreign key("project_log_id") references "project_logs"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "projects" ("id" integer primary key autoincrement not null, "contractor_id" integer not null, "nama_pekerjaan" varchar not null, "nilai_kontrak" integer not null, "tahun_anggaran" integer not null, "status" varchar not null, "progress" numeric not null default ('0'), "latitude" double not null, "longitude" double not null, "detail_lokasi" text, "created_at" datetime, "updated_at" datetime, "tanggal_kontrak" date, "tanggal_pelaksanaan" date, "tanggal_pemeriksaan" date, "tanggal_deadline" date, "reported_progress" numeric, "reported_photo" varchar, "reported_at" datetime, "verification_status" varchar not null default ('clean'), "verification_note" text, "ruas_jalan_id" integer, "ruas_jalan_nomor" varchar, "ruas_jalan_nama" varchar, "pengawas_verified_at" datetime, "pengawas_verified_by" integer, "final_verification_note" text, "final_verified_at" datetime, "final_verified_by" integer, "pengawas_id" integer, foreign key("final_verified_by") references users("id") on delete set null on update no action, foreign key("pengawas_verified_by") references users("id") on delete set null on update no action, foreign key("contractor_id") references contractors("id") on delete cascade on update no action, foreign key("pengawas_id") references "users"("id") on delete set null);
PRAGMA writable_schema=ON;
CREATE TABLE IF NOT EXISTS sqlite_sequence(name,seq);
DELETE FROM sqlite_sequence;
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "contractors_nib_unique" on "contractors" ("nib");
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE UNIQUE INDEX "training_participants_training_id_nik_unique" on "training_participants" ("training_id", "nik");
CREATE INDEX "projects_ruas_jalan_id_index" on "projects" ("ruas_jalan_id");
PRAGMA writable_schema=OFF;
COMMIT;
